from common import save
S = [
("What is the International Space Station?","The International Space Station (ISS) is a science lab orbiting Earth about 400 km up, once every 90 minutes, built by the USA, Russia, Europe, Japan and Canada. People have lived on it continuously since 2000.",["iss","international space station"]),
("What is the nearest star to Earth?","After the Sun, the nearest star is Proxima Centauri, about 4.24 light years away, part of the Alpha Centauri system.",["nearest star","proxima centauri","closest star to earth"]),
("What is a comet?","A comet is a ball of ice, dust and rock orbiting the Sun. Near the Sun it heats up and grows a glowing head and long tails. Halley's Comet returns about every 76 years (next in 2061).",["comet","halleys comet"]),
("What is an asteroid and a meteor?","An asteroid is a rocky object orbiting the Sun, mostly in the belt between Mars and Jupiter. A meteoroid is a small piece of space rock; when it burns up in our air it's a meteor (shooting star), and if it lands it's a meteorite.",["asteroid","meteor","meteorite","shooting star","asteroid belt"]),
("What is a satellite?","A satellite is an object that orbits a planet. The Moon is Earth's natural satellite; artificial satellites are used for communication, weather, navigation (GPS, India's NavIC) and research. India's first satellite was Aryabhata (1975).",["satellite","first indian satellite","aryabhata satellite","navic"]),
("What is gravity on the Moon?","Gravity on the Moon is about 1/6 of Earth's, so you'd weigh six times less there. The Moon has no air, so there's no sound, wind or weather.",["gravity on moon","weight on moon"]),
("What is the Big Bang?","The Big Bang theory says the universe began about 13.8 billion years ago from an extremely hot, dense state and has been expanding ever since. Evidence includes the cosmic microwave background and galaxies moving apart.",["big bang theory","age of the universe","how was the universe formed"]),
("What is Aditya-L1?","Aditya-L1 is India's first mission to study the Sun, launched by ISRO on 2 September 2023. It watches the Sun from the L1 point, about 1.5 million km from Earth.",["aditya l1","india sun mission"]),
("What is Gaganyaan?","Gaganyaan is ISRO's human spaceflight programme to send Indian astronauts (gaganyatris) into low Earth orbit, which would make India the fourth country to send humans to space on its own rocket.",["gaganyaan","indian human spaceflight"]),
("What is a nebula?","A nebula is a giant cloud of gas and dust in space. Some are where new stars are born (like the Orion Nebula); others are the remains of dying stars.",["nebula","orion nebula"]),
("What is a supernova?","A supernova is the enormous explosion of a massive star at the end of its life, briefly outshining a whole galaxy. It can leave behind a neutron star or a black hole.",["supernova","neutron star"]),
("What are the phases of a star's life?","A star forms in a nebula, shines as a main-sequence star (like the Sun) fusing hydrogen, swells into a red giant, and then becomes a white dwarf, or — if very massive — explodes as a supernova, leaving a neutron star or black hole.",["life cycle of a star","how stars are born","red giant","white dwarf"]),
("Why does Mars look red?","Mars looks red because its surface dust is rich in iron oxide (rust). It has the tallest volcano in the solar system, Olympus Mons, and two small moons, Phobos and Deimos.",["mars facts","olympus mons","moons of mars"]),
("What is Jupiter's Great Red Spot?","Jupiter's Great Red Spot is a giant storm, wider than Earth, that has been raging for at least 350 years.",["great red spot","jupiter facts"]),
("How long is a day on other planets?","One day (one spin): Mercury 59 Earth days, Venus 243 Earth days (longer than its year, and it spins backwards), Earth 24 h, Mars 24 h 37 min, Jupiter about 10 h (the fastest), Saturn about 10.7 h.",["day length on planets","longest day planet","venus day"]),
]
save("space2", "More about space", S)
